impl BenchmarkCampaign {
    pub(crate) fn new(plan: BenchmarkCampaignPlan) -> Result<Self, String> {
        let plan_fingerprint = plan.fingerprint()?;
        let runs = plan
            .schedule()?
            .into_iter()
            .map(|schedule| CampaignRunProgress {
                schedule,
                status: CampaignRunStatus::Pending,
                pre_measurement_retries: 0,
                record: None,
                failure: None,
            })
            .collect();
        let now = unix_ms();
        Ok(Self {
            schema_version: CAMPAIGN_SCHEMA_VERSION,
            plan,
            plan_fingerprint,
            state: BenchmarkCampaignState::Draft,
            runs,
            created_unix_ms: now,
            updated_unix_ms: now,
        })
    }

    pub(crate) fn preflight(
        &self,
        installed: &[BenchmarkModelIdentity],
    ) -> Result<CampaignPreflight, String> {
        self.plan.validate()?;
        let installed = installed
            .iter()
            .map(CampaignRepresentation::from_model)
            .collect::<BTreeSet<_>>();
        let mut missing = Vec::new();
        for candidate in &self.plan.candidates {
            if installed.contains(&candidate.representation) {
                continue;
            }
            let source_reference = candidate
                .source
                .source_reference
                .clone()
                .ok_or_else(|| format!("missing source for `{}`", candidate.representation.model_id))?;
            let license = candidate
                .source
                .license
                .clone()
                .ok_or_else(|| format!("missing license for `{}`", candidate.representation.model_id))?;
            let expected_sha256 = candidate
                .source
                .expected_sha256
                .clone()
                .ok_or_else(|| format!("missing SHA-256 for `{}`", candidate.representation.model_id))?;
            let transfer_size_bytes = candidate.source.transfer_size_bytes.ok_or_else(|| {
                format!("missing transfer size for `{}`", candidate.representation.model_id)
            })?;
            let storage_size_bytes = candidate.source.storage_size_bytes.ok_or_else(|| {
                format!("missing storage size for `{}`", candidate.representation.model_id)
            })?;
            missing.push(CampaignMissingCandidate {
                representation: candidate.representation.clone(),
                source_reference,
                license,
                expected_sha256,
                transfer_size_bytes,
                storage_size_bytes,
            });
        }
        Ok(CampaignPreflight {
            plan_fingerprint: self.plan_fingerprint.clone(),
            total_transfer_size_bytes: missing.iter().fold(0_u64, |total, item| {
                total.saturating_add(item.transfer_size_bytes)
            }),
            total_storage_size_bytes: missing.iter().fold(0_u64, |total, item| {
                total.saturating_add(item.storage_size_bytes)
            }),
            missing,
        })
    }

    pub(crate) fn validate_download_approval(
        &self,
        preflight: &CampaignPreflight,
        approval: &CampaignDownloadApproval,
    ) -> Result<(), String> {
        let expected = preflight
            .missing
            .iter()
            .map(|missing| missing.representation.clone())
            .collect::<Vec<_>>();
        if preflight.plan_fingerprint != self.plan_fingerprint
            || approval.plan_fingerprint != self.plan_fingerprint
            || approval.approved_missing != expected
        {
            return Err("Download & Run approval must match the exact frozen missing set".to_owned());
        }
        Ok(())
    }

    pub(crate) fn start(&mut self, installed: &[BenchmarkModelIdentity]) -> Result<(), String> {
        if self.state != BenchmarkCampaignState::Draft {
            return Err("campaign can only start from Draft".to_owned());
        }
        if !self.preflight(installed)?.missing.is_empty() {
            return Err("campaign still contains unverified missing representations".to_owned());
        }
        self.state = BenchmarkCampaignState::Running;
        self.touch();
        Ok(())
    }

    pub(crate) fn begin_next_run(&mut self) -> Result<Option<CampaignRunRequest>, String> {
        if self.state != BenchmarkCampaignState::Running {
            return Ok(None);
        }
        if self.has_active_run() {
            return Err("measured local campaign execution is sequential".to_owned());
        }
        let Some(index) = self
            .runs
            .iter()
            .position(|run| run.status == CampaignRunStatus::Pending)
        else {
            self.state = BenchmarkCampaignState::Completed;
            self.touch();
            return Ok(None);
        };
        self.runs[index].status = CampaignRunStatus::Preparing;
        let request = self.run_request(self.runs[index].schedule.clone())?;
        self.touch();
        Ok(Some(request))
    }

    pub(crate) fn preparing_run_request(&self) -> Result<Option<CampaignRunRequest>, String> {
        self.request_for_status(CampaignRunStatus::Preparing)
    }

    pub(crate) fn running_run_request(&self) -> Result<Option<CampaignRunRequest>, String> {
        self.request_for_status(CampaignRunStatus::Running)
    }

    fn request_for_status(
        &self,
        status: CampaignRunStatus,
    ) -> Result<Option<CampaignRunRequest>, String> {
        let matches = self
            .runs
            .iter()
            .filter(|run| run.status == status)
            .collect::<Vec<_>>();
        if matches.len() > 1 {
            return Err("campaign persistence contains multiple active runs".to_owned());
        }
        matches
            .first()
            .map(|run| self.run_request(run.schedule.clone()))
            .transpose()
    }

    fn run_request(&self, schedule: CampaignScheduleEntry) -> Result<CampaignRunRequest, String> {
        let candidate = self
            .plan
            .candidates
            .get(schedule.candidate_index)
            .ok_or_else(|| "campaign candidate index is invalid".to_owned())?;
        let runtime = self
            .plan
            .runtime_identity(schedule.execution_environment)?;
        let model = BenchmarkModelIdentity {
            backend_id: candidate.representation.backend_id.clone(),
            model_id: candidate.representation.model_id.clone(),
            model_version: TelemetryValue::Measured(candidate.representation.model_version.clone()),
            quantization: TelemetryValue::Measured(candidate.representation.quantization.clone()),
            representation_size_bytes: TelemetryValue::Measured(
                candidate.representation.representation_size_bytes,
            ),
            backend_runtime_version: TelemetryValue::Measured(
                runtime.backend_runtime_version.clone(),
            ),
        };
        let fixture = self
            .plan
            .tasks
            .get(schedule.task_index)
            .ok_or_else(|| "campaign task index is invalid".to_owned())?
            .fixture
            .clone();
        let candidate_contract = fixture.candidate_contract(&schedule.task_id)?;
        let reset_hash = stable_hash(
            format!(
                "{}:{}:{}:{}:{}",
                self.plan_fingerprint,
                schedule.task_id,
                schedule.repetition,
                schedule.candidate_index,
                schedule.execution_environment.identity()
            )
            .as_bytes(),
        );
        Ok(CampaignRunRequest {
            campaign_fingerprint: self.plan_fingerprint.clone(),
            harness: campaign_task_harness(&schedule.task_id)?,
            schedule,
            model,
            fixture,
            candidate_contract,
            reset_instance_id: format!("run-{reset_hash:016x}"),
        })
    }

